import unittest
from candidate import smallest_change

class TestSmallestChange(unittest.TestCase):
    def test_normal_case_even_length(self):
        self.assertEqual(smallest_change([1, 2, 3, 5, 4, 7, 9, 6]), 4)

    def test_normal_case_odd_length(self):
        self.assertEqual(smallest_change([1, 2, 3, 4, 3, 2, 2]), 1)

    def test_already_palindrome(self):
        self.assertEqual(smallest_change([1, 2, 3, 2, 1]), 0)

    def test_empty_array(self):
        self.assertEqual(smallest_change([]), 0)

    def test_single_element(self):
        self.assertEqual(smallest_change([5]), 0)

    def test_all_elements_same(self):
        self.assertEqual(smallest_change([7, 7, 7, 7]), 0)

    def test_mismatched_pairs(self):
        self.assertEqual(smallest_change([1, 2, 3, 4, 5]), 3)

    def test_odd_mismatches(self):
        self.assertEqual(smallest_change([1, 2, 3, 2, 4]), 2)

    def test_negative_numbers(self):
        self.assertEqual(smallest_change([-1, -2, -3, -2, -1]), 0)
        self.assertEqual(smallest_change([-1, -2, -3, -4, -1]), 2)

    def test_mixed_numbers(self):
        self.assertEqual(smallest_change([1, -2, 3, -4, 5]), 3)

    def test_duplicate_mismatches(self):
        self.assertEqual(smallest_change([1, 1, 2, 2, 3, 3, 1]), 1)

    def test_type_error_invalid_input(self):
        with self.assertRaises(TypeError):
            smallest_change("not_an_array")

    def test_none_input(self):
        with self.assertRaises(TypeError):
            smallest_change(None)

    def test_non_integer_elements(self):
        with self.assertRaises(TypeError):
            smallest_change([1, 2, "three", 4])

    def test_large_array(self):
        arr = [1] * 1000 + [2] * 1000
        self.assertEqual(smallest_change(arr), 1000)
